// Drops machine-generated mail before it reaches the model, and
// normalises the fields the rest of the workflow relies on.
//
// noreply@ senders are deliberately NOT blocked: many website contact
// forms deliver genuine customer enquiries from a noreply address and
// put the customer in Reply-To. Blocking them discards real mail.

const cfg = $('Settings').first().json;
const EXCERPT_LENGTH = Number(cfg.excerpt_length) || 300;

const SUBJECT_BLOCKLIST = [
  'auto-reply', 'autoreply', 'automatic reply', 'out of office', 'ooo:',
  'delivery status notification', 'undelivered mail', 'mail delivery failed',
  'returned mail', 'unsubscribe confirmation',
];
const SENDER_BLOCKLIST = ['mailer-daemon', 'postmaster@', 'bounce@', 'bounces@'];

// With Simplify off, Gmail returns addresses as objects rather than
// strings. Flatten whatever shape arrives into "Name <address>".
function addressToText(value) {
  if (!value) return '';
  if (typeof value === 'string') return value.trim();
  if (typeof value.text === 'string' && value.text.trim()) return value.text.trim();
  const list = Array.isArray(value) ? value : value.value;
  if (Array.isArray(list)) {
    return list.map((e) => {
      if (typeof e === 'string') return e.trim();
      const a = String(e?.address ?? '').trim();
      const n = String(e?.name ?? '').trim();
      return n && a ? n + ' <' + a + '>' : (a || n);
    }).filter(Boolean).join(', ');
  }
  return '';
}

function stripHtml(html) {
  return String(html ?? '')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const out = [];

$input.all().forEach((item, index) => {
  const j = item.json;
  const subject = String(j.subject ?? '');
  const from = addressToText(j.from);
  const replyTo = addressToText(j.replyTo) || from;

  const s = subject.toLowerCase();
  const f = from.toLowerCase();
  if (SUBJECT_BLOCKLIST.some((p) => s.includes(p))) return;
  if (SENDER_BLOCKLIST.some((p) => f.includes(p))) return;

  const body = String(j.text ?? '').trim() || stripHtml(j.html);
  if (!subject && !body) return;

  out.push({
    json: {
      message_id: j.id ?? '',
      received_at: j.date ? new Date(j.date).toISOString() : new Date().toISOString(),
      from,
      reply_to: replyTo,
      subject,
      body: body.slice(0, 4000),
      excerpt: body.replace(/\s+/g, ' ').trim().slice(0, EXCERPT_LENGTH),
    },
    pairedItem: { item: index },
  });
});

return out;

// Checks the model's answer against allow-lists. A value that is
// missing or out of range is replaced AND recorded, so a corrected
// row never looks like a clean one.
//
// It also escapes anything that Google Sheets would treat as a
// formula. A subject beginning with = + - @ (even behind spaces,
// tabs or a byte-order mark) becomes a live formula once written.

const CATEGORIES = ['refund_return', 'shipping', 'product_question', 'complaint', 'other'];
const PRIORITIES = ['high', 'medium', 'low'];
const SENTIMENTS = ['positive', 'neutral', 'negative'];
const LANGUAGES  = ['ja', 'en', 'other'];
const MAX_TEXT   = 300;

const FORMULA_START = /^[\s\uFEFF]*[=+\-@]/;
function safeForSheet(value) {
  const text = String(value ?? '');
  if (text === '') return '';
  return FORMULA_START.test(text) ? "'" + text : text;
}

function clip(value, limit) {
  return String(value ?? '').replace(/\s+/g, ' ').trim().slice(0, limit);
}

function pick(raw, allowed, fallback, flags, field) {
  const v = String(raw ?? '').toLowerCase().trim();
  if (allowed.includes(v)) return v;
  flags.push(field);
  return fallback;
}

function parseJson(raw) {
  try {
    const cleaned = String(raw).replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim();
    const v = JSON.parse(cleaned);
    return v && typeof v === 'object' && !Array.isArray(v) ? v : null;
  } catch (e) {
    return null;
  }
}

return $input.all().map((item, index) => {
  const src = $('Filter out machine-generated mail').all()[index].json;

  // Covers the HTTP Request node and the common AI node shapes.
  const raw =
    item.json?.choices?.[0]?.message?.content ??
    item.json?.message?.content ??
    item.json?.content ??
    item.json?.output ??
    item.json?.text ??
    '';

  const parsed = parseJson(raw);
  const flags = [];
  let result;

  if (!parsed) {
    result = {
      category: 'manual_review',
      priority: 'high',
      sentiment: 'neutral',
      language: 'other',
      summary: 'AI classification failed. Manual review required.',
      recommended_action: 'Open the original email and handle it manually.',
      ai_status: 'parse_failed',
    };
  } else {
    const summary = clip(parsed.summary, MAX_TEXT);
    const action  = clip(parsed.recommended_action, MAX_TEXT);
    if (!summary) flags.push('summary');
    if (!action) flags.push('recommended_action');
    result = {
      category: pick(parsed.category, CATEGORIES, 'other', flags, 'category'),
      priority: pick(parsed.priority, PRIORITIES, 'high', flags, 'priority'),
      sentiment: pick(parsed.sentiment, SENTIMENTS, 'neutral', flags, 'sentiment'),
      language: pick(parsed.language, LANGUAGES, 'other', flags, 'language'),
      summary: summary || 'Not provided by the model.',
      recommended_action: action || 'Read this email and decide.',
      ai_status: flags.length ? 'partial' : 'ok',
    };
    // Anything the model did not answer cleanly goes to a human.
    if (flags.length) result.priority = 'high';
  }

  return {
    json: {
      received_at: src.received_at,
      from: safeForSheet(src.from),
      reply_to: safeForSheet(src.reply_to),
      subject: safeForSheet(src.subject),
      excerpt: safeForSheet(src.excerpt),
      category: result.category,
      summary: safeForSheet(result.summary),
      recommended_action: safeForSheet(result.recommended_action),
      priority: result.priority,
      sentiment: result.sentiment,
      language: result.language,
      ai_status: result.ai_status,
      ai_substituted_fields: flags.join(', '),
      status: 'Open',
    },
    pairedItem: { item: index },
  };
});
